package glob

import "testing"

func TestExactMatch(t *testing.T) {
	if !Match("hello", "hello") {
		t.Error("expected exact match")
	}
	if Match("hello", "world") {
		t.Error("expected no match")
	}
}

func TestStar(t *testing.T) {
	if !Match("*.go", "main.go") {
		t.Error("*.go should match main.go")
	}
	if Match("*.go", "main.py") {
		t.Error("*.go should not match main.py")
	}
	if !Match("*", "anything") {
		t.Error("* should match anything")
	}
	if !Match("*", "") {
		t.Error("* should match empty string")
	}
}

func TestQuestion(t *testing.T) {
	if !Match("h?llo", "hello") {
		t.Error("h?llo should match hello")
	}
	if !Match("h?llo", "hxllo") {
		t.Error("h?llo should match hxllo")
	}
	if Match("h?llo", "hllo") {
		t.Error("h?llo should not match hllo (? requires 1 char)")
	}
}

func TestCombined(t *testing.T) {
	if !Match("*_test.go", "foo_test.go") {
		t.Error("expected match")
	}
	if !Match("?oo*", "foobar") {
		t.Error("?oo* should match foobar")
	}
	if Match("?oo*", "oobar") {
		t.Error("?oo* should not match oobar")
	}
}

func TestEdgeCases(t *testing.T) {
	if !Match("", "") {
		t.Error("empty pattern should match empty text")
	}
	if Match("", "a") {
		t.Error("empty pattern should not match non-empty text")
	}
	if !Match("**", "hello") {
		t.Error("** should match hello")
	}
}
